package com.coffeeshop.model;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.List;public final class ExpenseModels{private ExpenseModels(){}public record Category(long id,String code,String name,boolean active,byte[]version){public Category{version=version.clone();}@Override public byte[]version(){return version.clone();}@Override public String toString(){return name+(active?"":" (inactive)");}}public record Expense(long id,String number,long categoryId,String categoryName,LocalDateTime expensedAt,BigDecimal amount,String description,String reference,String notes,String recordedBy,byte[]version){public Expense{version=version.clone();}@Override public byte[]version(){return version.clone();}}public record Catalog(List<Category>categories,List<Expense>expenses){public Catalog{categories=List.copyOf(categories);expenses=List.copyOf(expenses);}}}
